const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
// В sandbox-просмотрщике localStorage может быть запрещён. Безопасное хранилище
// не даёт всему приложению остановиться из-за SecurityError.
const memoryStorage = {};
const storage = {
  getItem(key){ try { return window.localStorage.getItem(key) } catch { return memoryStorage[key] ?? null } },
  setItem(key,value){ try { window.localStorage.setItem(key,value) } catch { memoryStorage[key]=String(value) } },
  removeItem(key){ try { window.localStorage.removeItem(key) } catch { delete memoryStorage[key] } }
};
const state = { token:storage.getItem('pulse_token'), me:null, spaces:[], space:null, channel:null, dm:null, socket:null, online:new Set(), typing:new Map(), voice:null, localStream:null, peers:new Map(), voiceUsers:new Map(), audioContext:null, meterFrame:null, speaking:false, speakingTimer:null, voiceCount:0, currentRms:0, pendingAttachment:null, iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}] };
const prefs=JSON.parse(storage.getItem('pulse_prefs')||'{"compact":false,"reduceMotion":false,"notifications":true}');
function applyPrefs(){document.body.classList.toggle('compact',!!prefs.compact);document.body.classList.toggle('reduce-motion',!!prefs.reduceMotion)}
applyPrefs();
const authView=$('#authView'), appView=$('#appView'), modal=$('#modal'), modalBody=$('#modalBody');
const esc = (s='') => String(s).replace(/[&<>'"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const initials = name => String(name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const formatTime = date => new Intl.DateTimeFormat('ru',{hour:'2-digit',minute:'2-digit'}).format(new Date(date+'Z'));
const formatDay = date => new Intl.DateTimeFormat('ru',{day:'numeric',month:'long'}).format(new Date(date+'Z'));

async function api(url, options={}){
  const res=await fetch('/api'+url,{...options,headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`}:{ }),...options.headers}});
  const contentType=res.headers.get('content-type')||'';
  if(!contentType.includes('application/json')) throw new TypeError('Сервер чата недоступен');
  const data=await res.json().catch(()=>({}));
  if(res.status===401 && !url.startsWith('/auth/')) logout();
  if(!res.ok) throw new Error(data.error||'Что-то пошло не так');
  return data;
}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toastBox').append(el);setTimeout(()=>el.remove(),3000)}
function showModal(html){modalBody.innerHTML=html;modal.classList.remove('hidden')}
function closeModal(){modal.classList.add('hidden');modalBody.innerHTML=''}
$('#modalClose').onclick=closeModal; modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});

$$('.tab').forEach(tab=>tab.onclick=()=>{$$('.tab').forEach(x=>x.classList.toggle('active',x===tab));$('#loginForm').classList.toggle('hidden',tab.dataset.auth!=='login');$('#registerForm').classList.toggle('hidden',tab.dataset.auth!=='register');$('#authError').textContent=''});
$('#loginForm').onsubmit=e=>submitAuth(e,'/auth/login');
$('#registerForm').onsubmit=e=>submitAuth(e,'/auth/register');
$$('.password-toggle').forEach(btn=>btn.onclick=()=>{const input=$('input',btn.parentElement);input.type=input.type==='password'?'text':'password';btn.classList.toggle('active',input.type==='text')});
$('#registerForm [name="password"]').oninput=e=>{const v=e.target.value,score=[v.length>=8,/[a-zа-я]/i.test(v),/\d/.test(v),/[^a-zа-я0-9]/i.test(v)].filter(Boolean).length;const bar=$('.password-strength i');bar.style.width=`${score*25}%`;bar.dataset.score=score;$('.password-strength span').textContent=score<2?'Слабый пароль':score<4?'Хороший пароль':'Надёжный пароль'};
$('#forgotBtn').onclick=()=>toast('Восстановление пароля будет доступно после подключения почтового сервера');
async function submitAuth(e,url){
  e.preventDefault(); const form=e.currentTarget,btn=$('button[type="submit"]',form),oldText=btn.innerHTML;btn.disabled=true;btn.innerHTML=url.includes('register')?'Отправляем код…':'Подключаемся…';state.authenticating=true;$('#authError').textContent='';
  const fields=Object.fromEntries(new FormData(form));
  if(url.includes('register')&&fields.password!==fields.confirmPassword){$('#authError').textContent='Пароли не совпадают.';btn.disabled=false;btn.innerHTML=oldText;state.authenticating=false;return}
  try{
    const data=await api(url,{method:'POST',body:JSON.stringify(fields)});
    if(data.verificationRequired){openVerification(data.email,data.devCode);return}
    state.token=data.token;storage.setItem('pulse_token',data.token);await boot()
  }catch(err){
    if(err instanceof TypeError || /fetch|network|недоступен/i.test(err.message))$('#authError').textContent='Нет соединения с сервером. Открой Live Preview Pulse chat.';
    else $('#authError').textContent=err.message
  }finally{state.authenticating=false;btn.disabled=false;btn.innerHTML=oldText}
}
function openVerification(email,devCode){
  showModal(`<div class="verify-icon">✓</div><h2>Подтверди почту</h2><p>Мы отправили шестизначный код на <b>${esc(email)}</b>. Код действует 10 минут.</p>${devCode?`<div class="dev-code">Тестовый код: <b>${devCode}</b></div>`:''}<form id="verifyForm" class="modal-form"><label>Код подтверждения<input name="code" class="code-input" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" placeholder="000000" required></label><input type="hidden" name="email" value="${esc(email)}"><button class="primary">Подтвердить и войти</button></form>`);
  setTimeout(()=>$('[name="code"]',modalBody)?.focus(),100)
}
function bootOffline(username){
  state.offline=true;$('#offlineBanner').classList.remove('hidden');state.me={id:1,username,status:'Демо без сервера',accent:'#8b5cf6'};
  authView.classList.add('hidden');appView.classList.remove('hidden');paintMe();
  const space={id:1,name:'Орбита',description:'Локальная демонстрация',icon:'◉',role:'owner',members:1,channels:[{id:1,name:'общий',topic:'Демонстрационный канал Pulse'},{id:2,name:'идеи',topic:'Локальный канал'}]};
  state.spaces=[space];selectOfflineSpace(space);toast('Открыт локальный демо-режим');
}
function selectOfflineSpace(space){
  state.space=space;state.dm=null;if(!state.spaces.some(s=>s.id===space.id))state.spaces.push(space);renderSpaces();$('#spaceName').textContent=space.name;$('#channelSection').classList.remove('hidden');$('#dmSection').classList.add('hidden');$('#inviteBtn').classList.remove('hidden');$('#addChannelBtn').classList.remove('hidden');
  const channels=space.channels||[{id:space.id*100+1,name:'общий',topic:'Главный канал пространства'}];renderVoiceChannels([{id:space.id*100+90,name:'Лаунж'}]);$('#channelList').innerHTML=channels.map(c=>`<button class="channel-link" data-channel="${c.id}">${esc(c.name)}</button>`).join('');$$('[data-channel]').forEach(b=>b.onclick=()=>openOfflineChannel(channels.find(c=>c.id===+b.dataset.channel)));openOfflineChannel(channels[0]);
}
function openOfflineChannel(channel){
  state.channel=channel;state.dm=null;$$('.channel-link').forEach(x=>x.classList.toggle('active',+x.dataset.channel===channel.id));
  $('#chatSymbol').textContent='#';$('#chatTitle').textContent=channel.name;$('#chatTopic').textContent=channel.topic;$('#composer').classList.remove('hidden');
  const saved=JSON.parse(storage.getItem(`pulse_demo_${channel.id}`)||'[]');renderMessages(saved,'channel');
}
function logout(){state.socket?.emit('voice:leave');state.localStream?.getTracks().forEach(t=>t.stop());storage.removeItem('pulse_token');location.reload()}

async function boot(){
  try{state.me=await api('/me');try{const cfg=await api('/config');if(cfg.iceServers)state.iceServers=cfg.iceServers}catch{}authView.classList.add('hidden');appView.classList.remove('hidden');$('#offlineBanner').classList.add('hidden');paintMe();connectSocket();await loadSpaces();}
  catch{state.token=null;storage.removeItem('pulse_token');authView.classList.remove('hidden');appView.classList.add('hidden')}
}
function paintMe(){
  $('#myName').textContent=state.me.username;$('#myStatus').textContent=state.me.status;$('#myAvatar').textContent=initials(state.me.username);$('#myAvatar').style.background=state.me.accent;document.documentElement.style.setProperty('--accent',state.me.accent);
}
async function loadSpaces(selectId){
  state.spaces=await api('/spaces');renderSpaces();
  const picked=state.spaces.find(s=>s.id===selectId)||state.spaces.find(s=>s.id===state.space?.id)||state.spaces[0];
  if(picked) await selectSpace(picked); else openHome();
}
function renderSpaces(){
  $('#spaceRail').innerHTML=state.spaces.map(s=>`<button class="space-btn ${state.space?.id===s.id?'active':''}" data-space="${s.id}" title="${esc(s.name)}">${esc(s.icon||initials(s.name))}</button>`).join('');
  $$('[data-space]').forEach(b=>b.onclick=()=>selectSpace(state.spaces.find(s=>s.id===+b.dataset.space)));
}
async function selectSpace(space){
  state.space=space;state.dm=null;$('#spaceName').textContent=space.name;$('#channelSection').classList.remove('hidden');$('#dmSection').classList.add('hidden');$('#inviteBtn').classList.remove('hidden');$('#addChannelBtn').classList.toggle('hidden',!['owner','admin'].includes(space.role));renderSpaces();
  const channels=await api(`/spaces/${space.id}/channels`);$('#channelList').innerHTML=channels.map(c=>`<button class="channel-link" data-channel="${c.id}">${esc(c.name)}</button>`).join('');
  $$('[data-channel]').forEach(b=>b.onclick=()=>openChannel(channels.find(c=>c.id===+b.dataset.channel)));
  $('#addVoiceBtn').classList.toggle('hidden',!['owner','admin'].includes(space.role));
  try{renderVoiceChannels(await api(`/spaces/${space.id}/voice-channels`))}catch(e){toast(e.message)}
  if(channels.length) await openChannel(channels[0]);
}
function paintVoiceUsers(){if(!state.voice)return;const box=$(`[data-voice-users="${state.voice.id}"]`);if(box)box.innerHTML=[...state.voiceUsers.values()].map(u=>`<div class="voice-user-row ${u.speaking?'speaking':''}"><span class="voice-user-avatar ${u.speaking?'speaking':''}" style="background:${u.accent||'#8b5cf6'}">${initials(u.username)}</span><small>${esc(u.username)}${u.muted?' · выкл.':u.speaking?' · говорит':''}</small></div>`).join('');const count=$(`[data-voice-count="${state.voice.id}"]`);if(count)count.textContent=state.voiceUsers.size||''}
function updateVoiceStatus(){if(!state.voice)return;if(state.offline){$('#voiceStatusText').textContent='Проверка микрофона';$('#voiceConnectedName').textContent='Скажи что-нибудь для проверки';$('#voiceStateDot').classList.add('warning');return}const track=state.localStream?.getAudioTracks()[0],enabled=!!track?.enabled;const title=$('#voiceStatusText'),dot=$('#voiceStateDot');if(prefs.pushToTalk){title.textContent='Рация включена';dot.classList.add('warning');$('#voiceConnectedName').textContent=`${state.voice.name} · удерживай пробел`}else if(!enabled){title.textContent='Микрофон выключен';dot.classList.add('warning');$('#voiceConnectedName').textContent=`${state.voice.name} · нажми микрофон`}else{title.textContent='Голос подключён';dot.classList.remove('warning');$('#voiceConnectedName').textContent=`${state.voice.name} · ${Math.max(1,state.voiceCount)} в канале`}}
function setSpeaking(active){
  active=!!active&&!prefs.micMuted;clearTimeout(state.speakingTimer);
  if(!active&&state.speaking){state.speakingTimer=setTimeout(()=>setSpeakingNow(false),260);return}
  if(active!==state.speaking)setSpeakingNow(active)
}
function setSpeakingNow(active){state.speaking=active;const own=state.voiceUsers.get(state.socket?.id||'local');if(own){own.speaking=active;paintVoiceUsers()}$('#myAvatar').classList.toggle('speaking',active);if(state.offline&&state.voice){$('#voiceStatusText').textContent=active?'Микрофон слышит голос':'Проверка микрофона';$('#voiceConnectedName').textContent=active?'Всё работает — уровень сигнала есть':'Скажи что-нибудь для проверки';$('#voiceStateDot').classList.toggle('warning',!active)}state.socket?.emit('voice:speaking',{speaking:active})}
function startMicMeter(stream){
  try{state.audioContext?.close();const Ctx=window.AudioContext||window.webkitAudioContext;state.audioContext=new Ctx();state.audioContext.resume().catch(()=>{});const source=state.audioContext.createMediaStreamSource(stream),analyser=state.audioContext.createAnalyser();analyser.fftSize=512;analyser.smoothingTimeConstant=.55;source.connect(analyser);const data=new Uint8Array(analyser.fftSize),bars=$$('.mic-meter i');const tick=()=>{analyser.getByteTimeDomainData(data);let sum=0;for(const value of data){const sample=(value-128)/128;sum+=sample*sample}const rms=Math.sqrt(sum/data.length);state.currentRms=rms;bars.forEach((b,i)=>b.classList.toggle('on',rms>i*.025+.012));const trackActive=stream.getAudioTracks().some(t=>t.enabled&&t.readyState==='live'),threshold=Number(prefs.voiceThreshold||.028);setSpeaking(trackActive&&rms>threshold);state.meterFrame=requestAnimationFrame(tick)};tick()}catch{}
}
function stopMicMeter(){if(state.meterFrame)cancelAnimationFrame(state.meterFrame);state.meterFrame=null;clearTimeout(state.speakingTimer);setSpeakingNow(false);state.audioContext?.close().catch(()=>{});state.audioContext=null;$$('.mic-meter i').forEach(x=>x.classList.remove('on'))}
function renderVoiceChannels(channels){$('#voiceList').innerHTML=channels.map(c=>`<button class="voice-link ${state.voice?.id===c.id?'active':''}" data-voice="${c.id}"><span class="voice-channel-icon"><svg class="ui-icon"><use href="#i-volume"/></svg></span><span class="voice-channel-meta"><b>${esc(c.name)}</b><small>${state.voice?.id===c.id?'Подключено':'Нажми, чтобы войти'}</small></span><em data-voice-count="${c.id}"></em></button><div class="voice-users" data-voice-users="${c.id}"></div>`).join('');$$('[data-voice]').forEach(b=>b.onclick=()=>joinVoice(channels.find(c=>c.id===+b.dataset.voice)))}
async function joinVoice(channel){
  if(!navigator.mediaDevices?.getUserMedia)return toast('Открой Live Preview по HTTPS — там доступен микрофон');
  try{
    if(state.voice?.id===channel.id)return;
    await leaveVoice();if(!prefs.pushToTalk){prefs.micMuted=false;prefs.deafened=false;storage.setItem('pulse_prefs',JSON.stringify(prefs));syncAudioControls()}state.localStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true,...(prefs.voiceDevice?{deviceId:{exact:prefs.voiceDevice}}:{})},video:false});
    state.localStream.getAudioTracks().forEach(t=>t.enabled=!prefs.micMuted&&!prefs.pushToTalk);state.voice=channel;state.voiceCount=1;startMicMeter(state.localStream);$('#pttBtn').classList.toggle('active',!!prefs.pushToTalk);$('#pttBtn').classList.toggle('hidden',!!state.offline);
    $('#voiceConnected').classList.remove('hidden');updateVoiceStatus();$$('.voice-link').forEach(x=>x.classList.toggle('active',+x.dataset.voice===channel.id));
    if(state.offline){state.voiceUsers.set('local',{userId:state.me.id,username:state.me.username,accent:state.me.accent,muted:!!prefs.micMuted});paintVoiceUsers();const count=$(`[data-voice-count="${channel.id}"]`);if(count)count.textContent='';updateVoiceStatus();toast('Это только тест микрофона. Для разговора открой Live Preview');return}
    state.socket.emit('voice:join',{channelId:channel.id},result=>{if(result?.error){toast(result.error);leaveVoice();return}updateVoiceStatus();toast(`Подключено: ${channel.name}`)})
  }catch(e){toast(e.name==='NotAllowedError'?'Разреши доступ к микрофону в браузере':'Не удалось подключить микрофон')}
}
async function leaveVoice(){
  const previous=state.voice,voiceId=previous?.id;state.socket?.emit('voice:leave');state.peers.forEach(p=>p.close());state.peers.clear();stopMicMeter();state.localStream?.getTracks().forEach(t=>t.stop());state.localStream=null;state.voiceUsers.clear();
  if(voiceId){const users=$(`[data-voice-users="${voiceId}"]`),count=$(`[data-voice-count="${voiceId}"]`),link=$(`[data-voice="${voiceId}"]`);if(users)users.innerHTML='';if(count)count.textContent='';if(link){link.classList.remove('active');const hint=$('.voice-channel-meta small',link);if(hint)hint.textContent='Нажми, чтобы войти'}}
  state.voice=null;state.voiceCount=0;$('#remoteAudio').innerHTML='';$('#voiceConnected').classList.add('hidden');$$('.voice-link').forEach(x=>x.classList.remove('active'));$$('.voice-users').forEach(x=>x.innerHTML='');$$('[data-voice-count]').forEach(x=>x.textContent='');if(previous)toast(`Отключено: ${previous.name}`)
}
async function createPeer(socketId,initiator=false){
  if(state.peers.has(socketId))return state.peers.get(socketId);const pc=new RTCPeerConnection({iceServers:state.iceServers,iceCandidatePoolSize:4});state.peers.set(socketId,pc);state.localStream?.getTracks().forEach(t=>pc.addTrack(t,state.localStream));
  pc.onicecandidate=e=>{if(e.candidate)state.socket.emit('voice:signal',{target:socketId,signal:{candidate:e.candidate}})};
  pc.ontrack=e=>{let audio=$(`audio[data-peer="${socketId}"]`,$('#remoteAudio'));if(!audio){audio=document.createElement('audio');audio.dataset.peer=socketId;audio.autoplay=true;$('#remoteAudio').append(audio)}audio.srcObject=e.streams[0];audio.muted=!!prefs.deafened;audio.play().catch(()=>toast('Браузер заблокировал звук — нажми на страницу'))};
  pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){pc.close();state.peers.delete(socketId);$(`audio[data-peer="${socketId}"]`,$('#remoteAudio'))?.remove()}};
  if(initiator){const offer=await pc.createOffer();await pc.setLocalDescription(offer);state.socket.emit('voice:signal',{target:socketId,signal:{description:pc.localDescription}})}return pc
}
async function handleVoiceSignal({from,signal}){try{const pc=await createPeer(from,false);if(signal.description){await pc.setRemoteDescription(signal.description);if(signal.description.type==='offer'){const answer=await pc.createAnswer();await pc.setLocalDescription(answer);state.socket.emit('voice:signal',{target:from,signal:{description:pc.localDescription}})}}else if(signal.candidate)await pc.addIceCandidate(signal.candidate)}catch(e){console.warn('voice signal',e)}}
async function openChannel(channel){
  if(state.channel)state.socket?.emit('channel:leave',{channelId:state.channel.id});state.pendingAttachment=null;paintAttachment();state.channel=channel;state.dm=null;state.socket?.emit('channel:join',{channelId:channel.id});
  $$('.channel-link').forEach(x=>x.classList.toggle('active',+x.dataset.channel===channel.id));$$('.dm-link').forEach(x=>x.classList.remove('active'));
  $('#friendBtn').classList.add('hidden');$('#pinsBtn').classList.remove('hidden');$('#emptyActions').classList.add('hidden');$('#chatSymbol').textContent='#';$('#chatTitle').textContent=channel.name;$('#chatTopic').textContent=channel.topic||'Канал пространства';$('#messageInput').placeholder=`Написать в #${channel.name}`;$('#messageInput').value=storage.getItem(`draft_channel_${channel.id}`)||'';resizeInput();$('#composer').classList.remove('hidden');
  try{renderMessages(await api(`/channels/${channel.id}/messages`),'channel')}catch(e){toast(e.message)}
}
async function openHome(){
  state.channel=null;state.space=null;$('#spaceName').textContent='Личные сообщения';$('#channelSection').classList.add('hidden');$('#dmSection').classList.remove('hidden');$('#addChannelBtn').classList.add('hidden');$('#inviteBtn').classList.add('hidden');$('#pinsBtn').classList.add('hidden');renderSpaces();
  if(state.offline){$('#dmList').innerHTML='<p style="font-size:11px;color:#596176;padding:8px 10px">Личные сообщения доступны при запуске сервера</p>';$('#userSearch').disabled=true}
  else await loadDMs();
  if(!state.dm){$('#chatSymbol').textContent='◈';$('#chatTitle').textContent='Твои диалоги';$('#chatTopic').textContent='Найди человека и начни разговор';$('#messageList').innerHTML='';$('#welcomeEmpty').classList.remove('hidden');$('#welcomeEmpty h2').textContent='Разговоры начинаются здесь';$('#welcomeEmpty p').textContent='Найди человека, создай своё пространство или присоединись по приглашению.';$('#emptyActions').classList.remove('hidden');$('#composer').classList.add('hidden')}
}
$('#homeBtn').onclick=openHome;
$('#emptyFind').onclick=()=>{$('#userSearch').focus();appView.classList.add('menu-open')};
$('#emptyCreate').onclick=()=>$('#createSpaceBtn').click();
$('#emptyJoin').onclick=()=>$('#discoverBtn').click();
async function loadDMs(){
  const dms=await api('/dms'); renderDMList(dms);
}
function renderDMList(dms,search=false){
  const list=$('#dmList'); list.innerHTML=dms.map(d=>{const u=d.user||d;return `<button class="dm-link ${state.dm?.id===u.id?'active':''}" data-dm="${u.id}"><div class="avatar" style="background:${u.accent}">${initials(u.username)}</div><div><b>${esc(u.username)} ${state.online.has(u.id)?'<span style="color:#2dd4a0">•</span>':''}</b><small>${esc(search?'Начать диалог':(d.lastMessage||u.status||''))}</small></div></button>`}).join('')||'<p style="font-size:11px;color:#596176;padding:8px 10px">Пока нет диалогов</p>';
  $$('[data-dm]',list).forEach(b=>b.onclick=()=>openDM((dms.find(d=>(d.user||d).id===+b.dataset.dm).user||dms.find(d=>d.id===+b.dataset.dm))));
}
async function openDM(user){
  state.pendingAttachment=null;paintAttachment();state.dm=user;state.channel=null;$('#channelSection').classList.add('hidden');$('#dmSection').classList.remove('hidden');$('#emptyActions').classList.add('hidden');$('#friendBtn').classList.remove('hidden');$('#pinsBtn').classList.add('hidden');$('#chatSymbol').textContent='@';$('#chatTitle').textContent=user.username;$('#chatTopic').textContent=user.status||'Личный диалог';$('#messageInput').placeholder=`Сообщение для ${user.username}`;$('#messageInput').value=storage.getItem(`draft_dm_${user.id}`)||'';resizeInput();$('#composer').classList.remove('hidden');
  try{const data=await api(`/dms/${user.id}/messages`);state.dm=data.user;renderMessages(data.messages,'dm');await loadDMs()}catch(e){toast(e.message)}
}
let searchTimer;$('#userSearch').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=e.target.value.trim();if(!q)return loadDMs();try{renderDMList(await api(`/users?q=${encodeURIComponent(q)}`),true)}catch{}},250)};

function renderMessages(messages,type){
  const list=$('#messageList');let day='';list.innerHTML=messages.map(m=>{const d=formatDay(m.createdAt);const divider=d!==day?`<div class="day-divider">${day=d}</div>`:'';return divider+messageHTML(m,type)}).join('');
  $('#welcomeEmpty').classList.toggle('hidden',messages.length>0);if(!messages.length){$('#welcomeEmpty h2').textContent='Тишина перед разговором';$('#welcomeEmpty p').textContent='Напиши первое сообщение — иногда самые интересные истории начинаются с одного «привет».'}list.scrollTop=list.scrollHeight;bindMessageActions();
}
function attachmentHTML(a){if(!a)return '';if(String(a.type).startsWith('image/'))return `<a href="${esc(a.url)}" target="_blank" class="message-image"><img src="${esc(a.url)}" alt="${esc(a.name)}" loading="lazy"></a>`;return `<a href="${esc(a.url)}" target="_blank" class="message-file"><svg class="ui-icon"><use href="#i-paperclip"/></svg><span><b>${esc(a.name)}</b><small>Открыть вложение</small></span></a>`}
function messageHTML(m,type){return `<article class="message" data-message="${m.id}" data-type="${type}" data-content="${esc(m.content)}"><div class="avatar" style="background:${m.user.accent}">${initials(m.user.username)}</div><div>${m.replyTo?`<div class="reply-note">↳ ответ на сообщение</div>`:''}<div class="msg-head"><b>${esc(m.user.username)}</b><time>${formatTime(m.createdAt)}${m.edited?' · изм.':''}</time></div><div class="msg-text">${esc(m.content)}</div>${attachmentHTML(m.attachment)}<div class="reaction-row"></div></div><div class="msg-actions"><button class="msg-reply" title="Ответить">↩</button><button class="msg-react" title="Реакция">♡</button>${type==='channel'?'<button class="msg-pin" title="Закрепить">⌖</button>':''}${m.user.id===state.me.id?'<button class="msg-edit" title="Изменить">✎</button><button class="msg-delete" title="Удалить">×</button>':''}</div></article>`}
function appendMessage(m,type){
  $('#welcomeEmpty').classList.add('hidden');const list=$('#messageList');const wrap=document.createElement('div');wrap.innerHTML=messageHTML(m,type);list.append(wrap.firstElementChild);bindMessageActions();list.scrollTop=list.scrollHeight;
}
function bindMessageActions(){
  $$('.msg-delete').forEach(b=>b.onclick=async()=>{const a=b.closest('.message');if(!confirm('Удалить сообщение?'))return;if(state.offline){a.remove();return}try{await api(`/messages/${a.dataset.type}/${a.dataset.message}`,{method:'DELETE'})}catch(e){toast(e.message)}});
  $$('.msg-reply').forEach(b=>b.onclick=()=>{const a=b.closest('.message');state.replyTo=+a.dataset.message;$('#messageInput').placeholder=`Ответ на сообщение #${a.dataset.message}`;$('#messageInput').focus();toast('Режим ответа включён')});
  $$('.msg-edit').forEach(b=>b.onclick=async()=>{const a=b.closest('.message'),content=prompt('Изменить сообщение',a.dataset.content);if(!content?.trim()||content===a.dataset.content)return;if(state.offline){$('.msg-text',a).textContent=content;return}try{await api(`/messages/${a.dataset.type}/${a.dataset.message}`,{method:'PATCH',body:JSON.stringify({content})})}catch(e){toast(e.message)}});
  $$('.msg-react').forEach(b=>b.onclick=async()=>{const a=b.closest('.message'),emoji=prompt('Реакция: 👍 ❤️ 🔥 😂 🎉','👍');if(!emoji)return;if(state.offline){$('.reaction-row',a).innerHTML+=`<span>${esc(emoji)} 1</span>`;return}try{const out=await api(`/messages/${a.dataset.type}/${a.dataset.message}/reactions`,{method:'POST',body:JSON.stringify({emoji})});if(out.active)$('.reaction-row',a).innerHTML+=`<span>${esc(emoji)} 1</span>`}catch(e){toast(e.message)}});
  $$('.msg-pin').forEach(b=>b.onclick=async()=>{const a=b.closest('.message');if(state.offline)return toast('Сообщение закреплено в деморежиме');try{const out=await api(`/messages/channel/${a.dataset.message}/pin`,{method:'POST'});toast(out.pinned?'Сообщение закреплено':'Сообщение откреплено')}catch(e){toast(e.message)}})
}

$('#composer').onsubmit=e=>{e.preventDefault();sendMessage()};
$('#messageInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}};
function sendMessage(){
  const input=$('#messageInput'),content=input.value.trim(),attachment=state.pendingAttachment;if(!content&&!attachment)return;if(attachment?.uploading)return toast('Подожди окончания загрузки');
  if(state.offline){
    const key=`pulse_demo_${state.channel?.id||1}`,saved=JSON.parse(storage.getItem(key)||'[]');
    const message={id:Date.now(),content,attachment,replyTo:state.replyTo||null,createdAt:new Date().toISOString().replace('T',' ').replace('Z',''),user:state.me};
    saved.push(message);storage.setItem(key,JSON.stringify(saved.slice(-80)));appendMessage(message,'channel');storage.removeItem(`draft_channel_${state.channel?.id||1}`);state.pendingAttachment=null;paintAttachment();state.replyTo=null;input.value='';resizeInput();return;
  }
  if(!state.socket?.connected)return toast('Нет соединения с сервером');
  const event=state.channel?'channel:send':'dm:send';const payload=state.channel?{channelId:state.channel.id,content,replyTo:state.replyTo,attachment}:{recipientId:state.dm?.id,content,replyTo:state.replyTo,attachment};state.socket.emit(event,payload,r=>{if(r?.error)toast(r.error)});storage.removeItem(state.channel?`draft_channel_${state.channel.id}`:`draft_dm_${state.dm?.id}`);state.pendingAttachment=null;paintAttachment();state.replyTo=null;input.value='';resizeInput();stopTyping()
}
function resizeInput(){const el=$('#messageInput');el.style.height='auto';el.style.height=Math.min(el.scrollHeight,140)+'px';$('#charCount').textContent=el.value.length>1700?`${el.value.length}/2000`:''}
let typingTimeout;$('#messageInput').oninput=()=>{resizeInput();const key=state.channel?`draft_channel_${state.channel.id}`:state.dm?`draft_dm_${state.dm.id}`:null;if(key)storage.setItem(key,$('#messageInput').value);if(!state.socket)return;const info=state.channel?{type:'channel',id:state.channel.id}:{type:'dm',id:state.dm?.id};if(info.id){state.socket.emit('typing',{...info,active:true});clearTimeout(typingTimeout);typingTimeout=setTimeout(stopTyping,1200)}};
function stopTyping(){clearTimeout(typingTimeout);const info=state.channel?{type:'channel',id:state.channel.id}:{type:'dm',id:state.dm?.id};if(info.id)state.socket?.emit('typing',{...info,active:false})}
function paintAttachment(){const box=$('#attachmentPreview');if(!state.pendingAttachment){box.classList.add('hidden');box.innerHTML='';return}box.classList.remove('hidden');box.innerHTML=`<svg class="ui-icon"><use href="#i-paperclip"/></svg><span><b>${esc(state.pendingAttachment.name)}</b><small>${state.pendingAttachment.uploading?'Загрузка…':'Готово к отправке'}</small></span><button type="button" id="removeAttachment">×</button>`;$('#removeAttachment').onclick=()=>{state.pendingAttachment=null;paintAttachment()}}
$('#attachBtn').onclick=()=>$('#fileInput').click();
$('#fileInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>8*1024*1024)return toast('Файл больше 8 МБ');if(state.offline){state.pendingAttachment={url:URL.createObjectURL(file),name:file.name,type:file.type};paintAttachment();return}state.pendingAttachment={name:file.name,type:file.type,uploading:true};paintAttachment();const form=new FormData();form.append('file',file);try{const res=await fetch('/api/upload',{method:'POST',headers:{Authorization:`Bearer ${state.token}`},body:form});const data=await res.json();if(!res.ok)throw new Error(data.error);state.pendingAttachment=data;paintAttachment();toast('Файл загружен')}catch(err){state.pendingAttachment=null;paintAttachment();toast(err.message||'Ошибка загрузки')}};
$('#emojiBtn').onclick=()=>{const emojis=['😀','😂','😍','🤔','😎','😭','😡','👍','👎','❤️','🔥','🎉','✨','🚀','💡','✅','👀','🙏','💬','🎮'];showModal(`<h2>Эмодзи</h2><div class="emoji-grid">${emojis.map(e=>`<button data-emoji="${e}">${e}</button>`).join('')}</div>`);$$('[data-emoji]',modalBody).forEach(b=>b.onclick=()=>{const input=$('#messageInput');input.value+=b.dataset.emoji;closeModal();input.focus();resizeInput()})};
$('#friendBtn').onclick=async()=>{if(!state.dm||state.offline)return toast('Друзья доступны в серверном режиме');try{const out=await api(`/friends/${state.dm.id}`,{method:'POST'});toast(out.status==='accepted'?'Теперь вы друзья':'Заявка в друзья отправлена')}catch(e){toast(e.message)}};
$('#searchToggle').onclick=()=>{showModal(`<h2>Поиск сообщений</h2><p>Ищи по всем доступным каналам и личным диалогам.</p><div class="global-search"><svg class="ui-icon"><use href="#i-search"/></svg><input id="globalSearchInput" placeholder="Минимум 2 символа" autocomplete="off"></div><div id="searchResults" class="search-results"><div class="search-placeholder">Начни вводить текст сообщения</div></div>`);const input=$('#globalSearchInput',modalBody),results=$('#searchResults',modalBody);let timer;input.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=input.value.trim();if(q.length<2){results.innerHTML='<div class="search-placeholder">Минимум 2 символа</div>';return}if(state.offline){results.innerHTML='<div class="search-placeholder">Глобальный поиск доступен в Live Preview</div>';return}results.innerHTML='<div class="search-placeholder">Ищем…</div>';try{const rows=await api(`/search?q=${encodeURIComponent(q)}`);results.innerHTML=rows.map(r=>`<button class="search-result"><span>${r.type==='channel'?'# '+esc(r.channel_name):'@ '+esc(r.username)}</span><b>${esc(r.content)}</b><small>${r.type==='channel'?esc(r.space_name):'Личный диалог'}</small></button>`).join('')||'<div class="search-placeholder">Ничего не найдено</div>'}catch(e){results.innerHTML=`<div class="search-placeholder">${esc(e.message)}</div>`}},250)};setTimeout(()=>input.focus(),80)};
$('#pinsBtn').onclick=async()=>{$('#pinsBtn').classList.remove('has-update');if(!state.channel)return;if(state.offline)return showModal('<h2>Закреплённые сообщения</h2><p>В деморежиме закрепления не синхронизируются с сервером.</p>');showModal('<h2>Закреплённые сообщения</h2><p>Важное всегда под рукой.</p><div id="pinsList" class="pins-list"><div class="search-placeholder">Загрузка…</div></div>');try{const rows=await api(`/channels/${state.channel.id}/pins`);$('#pinsList',modalBody).innerHTML=rows.map(m=>`<div class="pin-item"><div class="avatar" style="background:${m.user.accent}">${initials(m.user.username)}</div><div><b>${esc(m.user.username)}</b><p>${esc(m.content)}</p></div></div>`).join('')||'<div class="search-placeholder">Закреплённых сообщений пока нет</div>'}catch(e){toast(e.message)}};

function connectSocket(){
  state.socket?.disconnect();state.socket=io({auth:{token:state.token}});
  state.socket.on('connect',()=>{if(state.channel)state.socket.emit('channel:join',{channelId:state.channel.id})});
  state.socket.on('disconnect',()=>{if(state.voice)leaveVoice()});
  state.socket.on('channel:message',({channelId,message})=>{if(state.channel?.id===channelId)appendMessage(message,'channel')});
  state.socket.on('dm:message',({senderId,recipientId,message})=>{const other=senderId===state.me.id?recipientId:senderId;if(state.dm?.id===other)appendMessage(message,'dm');else if(senderId!==state.me.id)toast(`Новое сообщение от ${message.user.username}`);loadDMs().catch(()=>{})});
  state.socket.on('message:deleted',({type,id})=>{const el=$(`.message[data-message="${id}"][data-type="${type}"]`);el?.remove()});
  state.socket.on('message:edited',({type,id,content})=>{const el=$(`.message[data-message="${id}"][data-type="${type}"]`);if(el){$('.msg-text',el).textContent=content;el.dataset.content=content;const time=$('time',el);if(time&&!time.textContent.includes('изм.'))time.textContent+=' · изм.'}});
  state.socket.on('pins:changed',({channelId})=>{if(state.channel?.id===channelId)$('#pinsBtn').classList.add('has-update')});
  state.socket.on('message:reaction',({type,id,emoji,active})=>{const el=$(`.message[data-message="${id}"][data-type="${type}"]`);if(!el)return;const row=$('.reaction-row',el);if(active)row.innerHTML+=`<span>${esc(emoji)}</span>`});
  state.socket.on('presence:list',ids=>{state.online=new Set(ids);updatePresence()});
  state.socket.on('presence',({userId,online})=>{online?state.online.add(userId):state.online.delete(userId);updatePresence()});
  state.socket.on('voice:state',({channelId,count})=>{const badge=$(`[data-voice-count="${channelId}"]`);if(badge)badge.textContent=count||'';if(state.voice?.id===channelId){state.voiceCount=count;updateVoiceStatus()}});
  state.socket.on('voice:members',async({members})=>{state.voiceCount=members.length+1;updateVoiceStatus();state.voiceUsers.clear();state.voiceUsers.set(state.socket.id,{userId:state.me.id,username:state.me.username,accent:state.me.accent,muted:!!prefs.micMuted});members.forEach(m=>state.voiceUsers.set(m.socketId,m));paintVoiceUsers();for(const m of members)await createPeer(m.socketId,true)});
  state.socket.on('voice:user-joined',u=>{state.voiceUsers.set(u.socketId,u);paintVoiceUsers()});
  state.socket.on('voice:user-left',({socketId})=>{state.peers.get(socketId)?.close();state.peers.delete(socketId);state.voiceUsers.delete(socketId);$(`audio[data-peer="${socketId}"]`,$('#remoteAudio'))?.remove();paintVoiceUsers()});
  state.socket.on('voice:signal',handleVoiceSignal);
  state.socket.on('voice:mute',({socketId,muted})=>{const u=state.voiceUsers.get(socketId);if(u){u.muted=muted;if(muted)u.speaking=false;paintVoiceUsers()}});
  state.socket.on('voice:speaking',({socketId,speaking})=>{const u=state.voiceUsers.get(socketId);if(u){u.speaking=speaking;paintVoiceUsers()}if(socketId===state.socket.id)$('#myAvatar').classList.toggle('speaking',speaking)});
  state.socket.on('typing',data=>{const matches=(data.type==='channel'&&state.channel?.id===data.id)||(data.type==='dm'&&state.dm?.id===data.id);if(!matches)return;data.active?state.typing.set(data.userId,data.username):state.typing.delete(data.userId);$('#typingBar').textContent=[...state.typing.values()].slice(0,2).join(', ')+(state.typing.size?' печатает…':'');if(data.active)setTimeout(()=>{state.typing.delete(data.userId);if(!state.typing.size)$('#typingBar').textContent=''},2500)});
}
function updatePresence(){const online=state.dm?state.online.has(state.dm.id):true;$('#onlineBadge').innerHTML=`<i style="background:${online?'#2dd4a0':'#596176'}"></i><span>${state.dm?(online?'в сети':'не в сети'):'в сети'}</span>`}

$('#inviteBtn').onclick=async()=>{if(!state.space)return;if(state.offline)return showModal('<h2>Приглашение</h2><p>Коды приглашения доступны в серверном режиме.</p>');try{const data=await api(`/spaces/${state.space.id}/invite`);showModal(`<h2>Пригласи людей</h2><p>Отправь этот код. По нему можно войти в пространство «${esc(state.space.name)}».</p><div class="invite-code">${esc(data.code)}</div><button id="copyInvite" class="primary wide">Скопировать код</button>`);$('#copyInvite').onclick=async()=>{await navigator.clipboard.writeText(data.code).catch(()=>{});toast('Код скопирован')}}catch(e){toast(e.message)}};
