modalBody.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='verifyForm'){const btn=$('button',e.target);btn.disabled=true;try{const data=await api('/auth/register/verify',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.token=data.token;storage.setItem('pulse_token',data.token);closeModal();await boot();toast('Почта подтверждена')}catch(err){toast(err.message);btn.disabled=false}return}if(e.target.id==='joinCodeForm'){if(state.offline){const code=Object.fromEntries(new FormData(e.target)).code||'DEMO';closeModal();selectOfflineSpace({id:Date.now(),name:`Пространство ${code.toUpperCase()}`,description:'Добавлено по демо-коду',icon:'◈',role:'member',members:1});toast('Код принят в деморежиме');return}try{const out=await api('/spaces/join-code',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();await loadSpaces(out.spaceId);toast('Пространство добавлено')}catch(err){toast(err.message)}return}if(e.target.id==='spaceForm'){const fields=Object.fromEntries(new FormData(e.target));if(state.offline){const space={id:Date.now(),name:fields.name,description:fields.description,icon:fields.icon||'✦',role:'owner',members:1};closeModal();selectOfflineSpace(space);toast('Пространство создано локально');return}try{const space=await api('/spaces',{method:'POST',body:JSON.stringify(fields)});closeModal();await loadSpaces(space.id);toast('Пространство создано')}catch(err){toast(err.message)}}if(e.target.id==='voiceChannelForm'){const fields=Object.fromEntries(new FormData(e.target));if(state.offline){closeModal();toast('Голосовые каналы доступны на сервере');return}try{await api(`/spaces/${state.space.id}/voice-channels`,{method:'POST',body:JSON.stringify(fields)});closeModal();renderVoiceChannels(await api(`/spaces/${state.space.id}/voice-channels`));toast('Голосовой канал создан')}catch(err){toast(err.message)}return}if(e.target.id==='channelForm'){const fields=Object.fromEntries(new FormData(e.target));if(state.offline){state.space.channels=state.space.channels||[{id:state.space.id*100+1,name:'общий',topic:'Главный канал пространства'}];state.space.channels.push({id:Date.now(),name:fields.name.toLowerCase().replace(/\s+/g,'-'),topic:fields.topic});closeModal();selectOfflineSpace(state.space);toast('Канал создан локально');return}try{const ch=await api(`/spaces/${state.space.id}/channels`,{method:'POST',body:JSON.stringify(fields)});closeModal();await selectSpace(state.space);toast(`Канал #${ch.name} создан`)}catch(err){toast(err.message)}}if(e.target.id==='profileForm'){const fields=Object.fromEntries(new FormData(e.target));if(state.offline){state.me={...state.me,status:fields.status,accent:fields.accent};paintMe();closeModal();toast('Профиль обновлён локально');return}try{state.me=await api('/me',{method:'PATCH',body:JSON.stringify(fields)});paintMe();closeModal();toast('Профиль обновлён')}catch(err){toast(err.message)}}});
$('#addVoiceBtn').onclick=()=>showModal(`<h2>Новый голосовой канал</h2><p>Место для живого разговора с участниками.</p><form id="voiceChannelForm" class="modal-form"><label>Название<input name="name" maxlength="30" required placeholder="Лаунж"></label><button class="primary">Создать голосовой канал</button></form>`);
$('#leaveVoiceBtn').onclick=leaveVoice;
$('#micTestBtn').onclick=()=>{if(!state.voice)return;const track=state.localStream?.getAudioTracks()[0],threshold=Number(prefs.voiceThreshold||.028);showModal(`<h2>Проверка голоса</h2><p>Говори в микрофон — зелёная рамка означает, что голос распознан.</p><div class="voice-diagnostics"><div><span>Микрофон</span><b>${track?.label?esc(track.label):'Не определён'}</b></div><div><span>Передача</span><b class="${track?.enabled?'ok':'bad'}">${track?.enabled?'Включена':'Выключена'}</b></div><div><span>Собеседники</span><b>${state.peers.size}</b></div><div><span>Режим</span><b>${state.offline?'Локальный тест':prefs.pushToTalk?'Рация':'Обычный'}</b></div></div><label class="sensitivity-control"><span>Чувствительность микрофона <b id="sensitivityValue">${Math.round(threshold*1000)}</b></span><input id="sensitivityRange" type="range" min="10" max="90" step="2" value="${Math.round(threshold*1000)}"><small>Ниже — чувствительнее, выше — меньше фонового шума</small></label><button id="autoCalibrateBtn" class="primary wide">Автокалибровка тишины</button><p class="voice-help">Для настоящего разговора между пользователями нужен Live Preview. Самого себя в наушниках слышно не будет — это нормально.</p>`);const range=$('#sensitivityRange',modalBody);range.oninput=()=>{$('#sensitivityValue',modalBody).textContent=range.value;prefs.voiceThreshold=Number(range.value)/1000;storage.setItem('pulse_prefs',JSON.stringify(prefs))};$('#autoCalibrateBtn',modalBody).onclick=()=>{const btn=$('#autoCalibrateBtn',modalBody);btn.disabled=true;btn.textContent='Сохраняй тишину…';setTimeout(()=>{const calibrated=Math.max(.018,Math.min(.08,state.currentRms*2.4+.008));prefs.voiceThreshold=calibrated;storage.setItem('pulse_prefs',JSON.stringify(prefs));range.value=Math.round(calibrated*1000);$('#sensitivityValue',modalBody).textContent=range.value;btn.textContent='Готово — чувствительность настроена';btn.disabled=false;toast('Микрофон откалиброван')},1600)}};
function setPttTalking(active){if(!state.voice||!prefs.pushToTalk)return;state.localStream?.getAudioTracks().forEach(t=>t.enabled=active);state.socket?.emit('voice:mute',{muted:!active});$('#pttBtn').classList.toggle('talking',active)}
$('#pttBtn').onclick=()=>{prefs.pushToTalk=!prefs.pushToTalk;storage.setItem('pulse_prefs',JSON.stringify(prefs));$('#pttBtn').classList.toggle('active',prefs.pushToTalk);if(state.voice){state.localStream?.getAudioTracks().forEach(t=>t.enabled=prefs.pushToTalk?false:!prefs.micMuted);state.socket?.emit('voice:mute',{muted:prefs.pushToTalk||prefs.micMuted});updateVoiceStatus()}toast(prefs.pushToTalk?'Рация включена — удерживай пробел':'Обычный режим микрофона')};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&prefs.pushToTalk&&state.voice&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();setPttTalking(true)}});document.addEventListener('keyup',e=>{if(e.code==='Space'&&prefs.pushToTalk){e.preventDefault();setPttTalking(false)}});
$('#addChannelBtn').onclick=()=>showModal(`<h2>Новый канал</h2><p>Создай отдельную тему внутри «${esc(state.space?.name)}».</p><form id="channelForm" class="modal-form"><label>Название<input name="name" maxlength="30" required placeholder="идеи"></label><label>Тема<input name="topic" maxlength="120" placeholder="Коротко о канале"></label><button class="primary">Создать канал</button></form>`);
$('#discoverBtn').onclick=async()=>{showModal('<h2>Открытые пространства</h2><p>Присоединяйся к сообществам или используй код приглашения.</p><form id="joinCodeForm" class="join-code-form"><input name="code" maxlength="16" placeholder="Код приглашения"><button class="mini-btn">Войти по коду</button></form><div class="discover-list">Загрузка…</div>');if(state.offline){const samples=[{id:71,name:'Творческая лаборатория',description:'Дизайн, музыка и идеи',icon:'✦',member_count:128},{id:72,name:'Игровая зона',description:'Собираем команды и играем',icon:'◉',member_count:84}];$('.discover-list',modalBody).innerHTML=samples.map(s=>`<div class="discover-item"><div class="discover-icon">${s.icon}</div><div class="discover-info"><b>${s.name}</b><small>${s.description} · ${s.member_count} участников</small></div><button class="mini-btn" data-local-join="${s.id}">Войти</button></div>`).join('');$$('[data-local-join]',modalBody).forEach(b=>b.onclick=()=>{const s=samples.find(x=>x.id===+b.dataset.localJoin);closeModal();selectOfflineSpace({...s,role:'member',members:s.member_count});toast('Демо-пространство добавлено')});return}try{const spaces=await api('/spaces/discover');$('.discover-list',modalBody).innerHTML=spaces.map(s=>`<div class="discover-item"><div class="discover-icon">${esc(s.icon)}</div><div class="discover-info"><b>${esc(s.name)}</b><small>${esc(s.description||`${s.member_count} участников`)}</small></div><button class="mini-btn" data-join="${s.id}" ${s.joined?'disabled':''}>${s.joined?'Внутри':'Войти'}</button></div>`).join('')||'<p>Пока ничего нет.</p>';$$('[data-join]',modalBody).forEach(b=>b.onclick=async()=>{await api(`/spaces/${b.dataset.join}/join`,{method:'POST'});closeModal();await loadSpaces(+b.dataset.join);toast('Ты в пространстве')})}catch(e){toast(e.message)}};
function openSettings(){const colors=['#8b5cf6','#06b6d4','#ec4899','#22c55e','#f59e0b'];showModal(`<div class="settings-head"><div><span class="mini-label">PULSE CONTROL</span><h2>Настройки</h2></div><span class="version-chip">v1.4.2</span></div><div class="settings-layout"><nav class="settings-nav"><button class="active" data-settings="profile">Профиль</button><button data-settings="appearance">Интерфейс</button><button data-settings="voice">Голос</button><button data-settings="security">Безопасность</button><button data-settings="updates">Обновления</button></nav><div class="settings-content"><section data-panel="profile"><h3>Твой профиль</h3><p>Так тебя видят остальные участники.</p><form id="profileForm" class="modal-form"><label>Статус<input name="status" maxlength="60" value="${esc(state.me.status)}"></label><label>Цвет профиля<div class="color-row">${colors.map(c=>`<button type="button" class="color-dot ${c===state.me.accent?'active':''}" style="background:${c}" data-color="${c}"></button>`).join('')}</div><input type="hidden" name="accent" value="${state.me.accent}"></label><button class="primary">Сохранить профиль</button></form></section><section data-panel="appearance" class="hidden"><h3>Интерфейс</h3><p>Настрой внешний вид чата.</p><label class="setting-row"><span><b>Компактные сообщения</b><small>Меньше отступов в переписке</small></span><input type="checkbox" data-pref="compact" ${prefs.compact?'checked':''}></label><label class="setting-row"><span><b>Уменьшить анимации</b><small>Отключает лишние переходы</small></span><input type="checkbox" data-pref="reduceMotion" ${prefs.reduceMotion?'checked':''}></label><label class="setting-row"><span><b>Уведомления</b><small>Показывать новые сообщения</small></span><input type="checkbox" data-pref="notifications" ${prefs.notifications?'checked':''}></label></section><section data-panel="voice" class="hidden"><h3>Голос и устройства</h3><p>Выбери микрофон и настрой чувствительность.</p><label class="device-select">Микрофон<select id="voiceDeviceSelect"><option value="">Системный микрофон</option></select></label><label class="sensitivity-control"><span>Чувствительность <b id="settingsSensitivityValue">${Math.round(Number(prefs.voiceThreshold||.028)*1000)}</b></span><input id="settingsSensitivity" type="range" min="10" max="90" step="2" value="${Math.round(Number(prefs.voiceThreshold||.028)*1000)}"><small>Ниже — чувствительнее</small></label><button type="button" id="refreshDevicesBtn" class="mini-btn">Обновить список устройств</button></section><section data-panel="security" class="hidden"><h3>Безопасность</h3><div class="security-card"><svg class="ui-icon"><use href="#i-shield"/></svg><div><b>Почта подтверждена</b><small>${esc(state.me.email||'Аккаунт защищён кодом')}</small></div><span>ПРОВЕРЕНО</span></div><p>При новой регистрации Pulse запрашивает шестизначный код. Код действует 10 минут, а число попыток ограничено.</p><button type="button" id="logoutBtn" class="danger-btn">Выйти из аккаунта</button></section><section data-panel="updates" class="hidden"><h3>Обновления</h3><div class="update-card"><svg class="ui-icon"><use href="#i-refresh"/></svg><div><b>Pulse 1.4.2</b><small id="updateStatus">Нажми, чтобы проверить версию сервера</small></div></div><button type="button" id="checkUpdateBtn" class="primary">Проверить обновления</button></section></div></div>`);
  $$('[data-settings]',modalBody).forEach(b=>b.onclick=()=>{$$('[data-settings]',modalBody).forEach(x=>x.classList.toggle('active',x===b));$$('[data-panel]',modalBody).forEach(p=>p.classList.toggle('hidden',p.dataset.panel!==b.dataset.settings))});
  $$('[data-color]',modalBody).forEach(b=>b.onclick=()=>{$$('[data-color]',modalBody).forEach(x=>x.classList.remove('active'));b.classList.add('active');$('input[name=accent]',modalBody).value=b.dataset.color});
  $$('[data-pref]',modalBody).forEach(i=>i.onchange=()=>{prefs[i.dataset.pref]=i.checked;storage.setItem('pulse_prefs',JSON.stringify(prefs));applyPrefs();toast('Настройка сохранена')});
  const loadDevices=async()=>{try{const devices=(await navigator.mediaDevices?.enumerateDevices())?.filter(d=>d.kind==='audioinput')||[],select=$('#voiceDeviceSelect',modalBody);select.innerHTML='<option value="">Системный микрофон</option>'+devices.map((d,i)=>`<option value="${esc(d.deviceId)}" ${prefs.voiceDevice===d.deviceId?'selected':''}>${esc(d.label||`Микрофон ${i+1}`)}</option>`).join('');select.onchange=()=>{prefs.voiceDevice=select.value;storage.setItem('pulse_prefs',JSON.stringify(prefs));toast('Микрофон выбран')}}catch{}};loadDevices();$('#refreshDevicesBtn',modalBody).onclick=loadDevices;$('#settingsSensitivity',modalBody).oninput=e=>{prefs.voiceThreshold=Number(e.target.value)/1000;$('#settingsSensitivityValue',modalBody).textContent=e.target.value;storage.setItem('pulse_prefs',JSON.stringify(prefs))};
  $('#logoutBtn',modalBody).onclick=logout;$('#checkUpdateBtn',modalBody).onclick=async()=>{const btn=$('#checkUpdateBtn',modalBody);btn.disabled=true;$('#updateStatus',modalBody).textContent='Проверяем сервер…';try{const data=await api('/health');$('#updateStatus',modalBody).textContent=`Установлена актуальная версия ${data.version||'1.4.2'}`;toast('Обновлений пока нет')}catch{$('#updateStatus',modalBody).textContent='Не удалось связаться с сервером'}finally{btn.disabled=false}}
}
$('#panelSettingsBtn').onclick=openSettings;$('#myAvatar').onclick=openSettings;
function syncAudioControls(){const mic=$('#micBtn'),sound=$('#soundBtn');mic.classList.toggle('active',!!prefs.micMuted);sound.classList.toggle('active',!!prefs.deafened);mic.title=prefs.micMuted?'Включить микрофон':'Выключить микрофон';sound.title=prefs.deafened?'Включить звук':'Отключить звук'}
$('#micBtn').onclick=()=>{prefs.micMuted=!prefs.micMuted;state.localStream?.getAudioTracks().forEach(t=>t.enabled=!prefs.micMuted&&!prefs.pushToTalk);state.socket?.emit('voice:mute',{muted:prefs.micMuted});if(prefs.micMuted)setSpeakingNow(false);storage.setItem('pulse_prefs',JSON.stringify(prefs));syncAudioControls();updateVoiceStatus();toast(prefs.micMuted?'Микрофон выключен':'Микрофон включён')};
$('#soundBtn').onclick=()=>{prefs.deafened=!prefs.deafened;if(prefs.deafened){prefs.micMuted=true;state.localStream?.getAudioTracks().forEach(t=>t.enabled=false);state.socket?.emit('voice:mute',{muted:true})}$$('#remoteAudio audio').forEach(a=>a.muted=!!prefs.deafened);storage.setItem('pulse_prefs',JSON.stringify(prefs));syncAudioControls();toast(prefs.deafened?'Звук отключён':'Звук включён')};syncAudioControls();

$('#mobileMenu').onclick=()=>appView.classList.add('menu-open');$('#closeMobileMenu').onclick=()=>appView.classList.remove('menu-open');$('#mobileShade').onclick=()=>appView.classList.remove('menu-open');$('#channelList').addEventListener('click',()=>appView.classList.remove('menu-open'));$('#dmList').addEventListener('click',()=>appView.classList.remove('menu-open'));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();appView.classList.remove('menu-open')}});

// Без действующей сессии всегда показываем настоящий экран входа.
// Гостевой автозапуск отключён.
if(state.token)boot();
